INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 50 anos, em tratamento para IAMssST há 24 horas (em uso de AAS, Ticagrelor e Enoxaparina), apresenta subitamente hematêmese volumosa e melena. O que deve ser feito em relação à terapia antitrombótica imediata?", "options": {"a": "Manter tudo e dar omeprazol.", "b": "Suspender temporariamente a antiagregação dupla e a anticoagulação; realizar estabilização hemodinâmica e endoscopia de urgência.", "c": "Trocar Ticagrelor por Clopidogrel.", "d": "Dar uma dose extra de heparina.", "e": "Fazer cateterismo imediato."}, "answer": "b", "rationale": "O sangramento ativo grave (BARC >= 3) exige a interrupção da terapia antitrombótica para controle do foco hemorrágico, com balanço de risco isquêmico vs hemorrágico.", "option_rationales": {"a": "Incorreta. Risco de morte por choque hemorrágico.", "b": "Correta. Prioridade clínica em sangramento maior.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Sangramento", "SCA", "Complicação"]}', 146, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal causa de insuficiência mitral (IM) aguda no contexto de um infarto do miocárdio de parede inferior é:", "options": {"a": "Calcificação da válvula.", "b": "Ruptura ou disfunção do músculo papilar póstero-medial (que possui irrigação única pela ACD ou ACX).", "c": "Dilatação do átrio esquerdo.", "d": "Febre reumática.", "e": "Endocardite."}, "answer": "b", "rationale": "O papilar póstero-medial é mais vulnerável à isquemia do que o antero-lateral (que tem irrigação dupla). Sua ruptura causa IM maciça e choque.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação mecânica clássica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "IAM", "Complicação", "Insuficiência Mitral"]}', 147, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O teste de inclinação (Tilt Test) é utilizado no diagnóstico diferencial de síncope para identificar:", "options": {"a": "Oclusão coronariana.", "b": "Síncope vasovagal (neurocardiogênica) através da indução de resposta reflexa hipotensora e/ou bradicárdica.", "c": "Asma brônquica.", "d": "Epilepsia.", "e": "AVC."}, "answer": "b", "rationale": "O Tilt Test avalia a integridade do reflexo autonômico na mudança de postura.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Indicação diagnóstica do exame.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Síncope", "Tilt Test", "Diagnóstico"]}', 148, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a conduta recomendada para um paciente com IAM com supra de ST que apresenta contraindicação absoluta à fibrinólise (ex: histórico de AVC hemorrágico prévio) em um hospital sem hemodinâmica?", "options": {"a": "Fazer o fibrinolítico assim mesmo.", "b": "Transferência imediata para centro com hemodinâmica (transfer para ICP primária), mesmo que passe de 120 minutos.", "c": "Apenas observar na UTI.", "d": "Fazer uma sangria.", "e": "Dar antibiótico."}, "answer": "b", "rationale": "Se a fibrinólise é proibida, a única opção de reperfusão é a transferência, independentemente do tempo, para tentar salvar o miocárdio.", "option_rationales": {"a": "Incorreta. Risco de morte por hemorragia cerebral.", "b": "Correta. Única alternativa viável de reperfusão.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Diretrizes", "SCA", "Fibrinólise"]}', 149, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre a Síndrome de Takotsubo (Síndrome do Coração Partido), qual o achado típico na ventriculografia esquerda?", "options": {"a": "Ventrículo normal.", "b": "Acinesia apical com hipercinesia basal (formato de armadilha de polvo).", "c": "Ventriculo em forma de ovo.", "d": "Ruptura de parede.", "e": "Trombo gigante."}, "answer": "b", "rationale": "O balonamento apical é o sinal patognomônico da cardiomiopatia por estresse.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Morfologia característica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Takotsubo", "Estresse", "SCA"]}', 150, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No tratamento de manutenção da DAOC (Doença Arterial Obstrutiva Coronariana), qual classe de hipolipemiantes demonstrou maior redução de eventos cardiovasculares?", "options": {"a": "Fibratos.", "b": "Estatinas de alta potência (Atorvastatina, Rosuvastatina).", "c": "Resinas.", "d": "Ômega 3 em baixas doses.", "e": "Vitamina C."}, "answer": "b", "rationale": "Estatinas reduzem o colesterol e têm efeitos pleiotrópicos estabilizadores de placa.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Pilar central da prevenção secundária.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Estatinas", "Colesterol", "SCA"]}', 151, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente de 75 anos revela calcificação coronariana severa (coronárias em ''trilho de trem''). Qual a dificuldade técnica que isso impõe à intervenção percutânea (ICP)?", "options": {"a": "Nenhuma.", "b": "Dificuldade de expansão adequada do stent e maior risco de fratura de balão/stent; pode exigir o uso de aterectomia rotacional (Rotablator) ou litotripsia (Shockwave).", "c": "O paciente não pode usar contraste.", "d": "O sangue fica mais ralo.", "e": "Causa febre."}, "answer": "b", "rationale": "O cálcio impede que o balão e o stent abram completamente, o que pode levar a trombose ou reestenose de stent precoce.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Desafio atual da cardiologia intervencionista.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Hemodinâmica", "Cálcio", "SCA"]}', 152, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal indicação para o uso de Nitrato endovenoso (Nitroglicerina) na fase aguda do IAM é:", "options": {"a": "Reduzir a pressão arterial sistêmica em todos os pacientes.", "b": "Tratar dor isquêmica persistente, hipertensão severa ou edema agudo de pulmão associado.", "c": "Prevenir a queda do cabelo.", "d": "Substituir a aspirina.", "e": "Tratar a hipercalemia."}, "answer": "b", "rationale": "O uso deve ser individualizado e cauteloso, evitando-se na presença de hipotensão ou infarto de VD.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Uso racional do nitrato venoso.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Nitrato", "SCA"]}', 153, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente com dor torácica atípica realiza um escore de cálcio coronariano pela tomografia, obtendo um valor de 0 (zero). Qual o significado clínico deste achado?", "options": {"a": "Risco de infarto em 1 ano é de 100%.", "b": "Altíssimo valor preditivo negativo para doença aterosclerótica coronariana significativa (risco de eventos muito baixo nos próximos anos).", "c": "O paciente tem câncer.", "d": "Precisa de cateterismo imediato.", "e": "O exame falhou."}, "answer": "b", "rationale": "O escore zero identifica o paciente de ''extra-baixo'' risco cardiovascular.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Utilidade clínica do escore de cálcio.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Escore de Cálcio", "Diagnóstico", "Risco"]}', 154, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente mostra uma bifurcação complexa com lesões em ambos os ramos (DA e Diagonal). O intervencionista opta pela técnica de ''Provisional Stenting''. No que consiste essa técnica?", "options": {"a": "Colocar dois stents de uma vez.", "b": "Colocar o stent no vaso principal e intervir no ramo lateral apenas se houver comprometimento do fluxo (fluxo TIMI < 3) ou lesão residual grave.", "c": "Não colocar stent nenhum.", "d": "Usar apenas balão.", "e": "Tirar o coração do peito."}, "answer": "b", "rationale": "A abordagem provisional é o padrão na maioria das bifurcações, reservando dois stents apenas para casos anátomicos desfavoráveis de saída.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Estratégia padrão de bifurcação.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Intervenção", "Bifurcação", "SCA"]}', 155, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal causa de reestenose intrastent em stents não farmacológicos (convencionais) é:", "options": {"a": "Trombose aguda.", "b": "Hiperplasia neointimal (reação cicatricial excessiva da parede do vaso ao metal).", "c": "Infecção por bactéria.", "d": "Falta de vitaminas.", "e": "Uso de café."}, "answer": "b", "rationale": "Os stents farmacológicos foram criados justamente para inibir essa proliferação celular com drogas citostáticas (ex: Sirolimus, Paclitaxel).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Processo biopatológico da reestenose.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Stent", "Reestenose", "Hemodinâmica"]}', 156, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal diferença entre a Troponina T e a Troponina I?", "options": {"a": "A Troponina T é exclusiva do pulmão.", "b": "A Troponina T pode estar elevada em pacientes com insuficiência renal crônica mesmo na ausência de SCA clara; a Troponina I é considerada discretamente mais cardio-específica.", "c": "A Troponina I é azul.", "d": "Não há diferença nenhuma.", "e": "A Troponina I só existe em mulheres."}, "answer": "b", "rationale": "Ambas são excelentes para o diagnóstico, mas o clínico deve estar atento a elevações basais de Tropo T em renais.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Nuance bioquímica dos biomarcadores.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Biomarcadores", "Troponina", "Diagnóstico"]}', 157, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A presença de ''efeito de lucidez'' (intervalo lúcido) seguido de deterioração neurológica rápida após um trauma craniano sugere hematoma epidural. Qual a relação desta condição com a cardiologia na sala de emergência?", "options": {"a": "Nenhuma.", "b": "É uma contraindicação absoluta para o uso de qualquer fibrinolítico se houver suspeita de dor torácica associada.", "c": "O paciente precisa de aspirina.", "d": "Aumenta o risco de infarto.", "e": "Cura a arritmia."}, "answer": "b", "rationale": "Trauma craniano recente e sangramentos intracranianos proíbem a fibrinólise química.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Segurança no manejo das urgências.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Segurança", "Fibrinólise", "SCA"]}', 158, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente idoso revela uma tortuosidade excessiva das artérias coronárias. Qual a principal dificuldade técnica?", "options": {"a": "O paciente sente dor.", "b": "Dificuldade de progressão de guias e entrega de stents (risco de kinking ou perfuração).", "c": "O contraste não passa.", "d": "O coração para de bater.", "e": "Aumenta a glicose."}, "answer": "b", "rationale": "Vias tortuosas exigem fios-guias mais firmes e técnicas de suporte.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Aspecto técnico da cardiologia intervencionista.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Hemodinâmica", "Tortuosidade", "SCA"]}', 159, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal causa de morte por complicações mecânicas após um infarto anterior extenso, ocorrendo geralmente entre o 3º e 7º dia?", "options": {"a": "Ruptura de parede livre do VE levando a tamponamento cardíaco.", "b": "Gripe.", "c": "Infecção urinária.", "d": "Cefaleia.", "e": "Queda da própria altura."}, "answer": "a", "rationale": "A necrose transmural máxima enfraquece o miocárdio, permitindo a ruptura.", "option_rationales": {"a": "Correta. Complicação mecânica fatal.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "IAM", "Ruptura", "Complicação"]}', 160, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A utilidade clínica do marcador PCR-ultrassensível na estratificação de risco cardiovascular primário é:", "options": {"a": "Diagnosticar infarto.", "b": "Identificar inflamação residual que aumenta o risco futuro de eventos isquêmicos, ajudando na decisão de intensificar a terapia com estatinas.", "c": "Ver se o paciente tem febre.", "d": "Medir o colesterol.", "e": "Ver se tem câncer."}, "answer": "b", "rationale": "A PCR us é um biomarcador de risco, não de diagnóstico de necrose aguda.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Uso da PCR na prevenção primária.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "PCR", "Risco", "Diagnóstico"]}', 161, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente com IAM com supra de ST realiza fibrinólise. Após 30 minutos, apresenta múltiplos episódios de Ritmo Ideoventricular Acelerado (RIVA). Qual a conduta?", "options": {"a": "Dar amiodarona endovenosa urgente.", "b": "Choque elétrico (desfibrilação).", "c": "Observar (o RIVA é um sinal de reperfusão bem-sucedida e geralmente é benigno e autolimitado).", "d": "Fazer massagem cardíaca.", "e": "Dar adrenalina."}, "answer": "c", "rationale": "O RIVA é a ''arritmia de reperfusão'', indicando que o sangue voltou ao miocárdio.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Reconhecimento de sinal de sucesso terapêutico.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "RIVA", "Reperfusão", "SCA"]}', 162, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia mostra uma artéria descendente anterior com fluxo TIMI 1. O que significa isso?", "options": {"a": "Fluxo normal.", "b": "O contraste penetra na área de obstrução, mas não consegue perfundir toda a artéria distalmente (fluxo muito lento).", "c": "Oclusão total sem passagem de contraste.", "d": "Passagem rápida e completa do contraste.", "e": "A artéria sumiu."}, "answer": "b", "rationale": "TIMI 0 (oclusão), TIMI 1 (passagem parcial sem lavar), TIMI 2 (passagem completa lenta), TIMI 3 (normal).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Classificação de fluxo coronariano.", "c": "Incorreta. Isso seria TIMI 0.", "d": "Incorreta. Isso seria TIMI 3.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "TIMI", "Fluxo coronariano", "SCA"]}', 163, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal recomendação para o uso de Nitratos em pacientes com suspeita de infarto de ventrículo direito (VD)?", "options": {"a": "Devem ser usados em doses altas.", "b": "Estão CONTRAINDICADOS, pois a redução da pré-carga pode levar a queda drástica do débito cardíaco e choque.", "c": "Não fazem diferença.", "d": "Devem ser dados junto com diuréticos.", "e": "Ajudam a abrir a coronária direita."}, "answer": "b", "rationale": "O VD infartado é dependente de volume (pré-carga) para manter o fluxo para o pulmão.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manobra de segurança fundamental.", "c": "Incorreta.", "d": "Incorreta. Diuréticos também reduzem volume e são perigosos aqui.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Infarto de VD", "Segurança", "SCA"]}', 164, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal causa de reintervenção em stents farmacológicos modernos é:", "options": {"a": "Trombose de stent precoce.", "b": "Progressão da doença aterosclerótica em outros segmentos (lesões de novo) ou neoaterosclerose dentro do stent.", "c": "Alergia ao metal.", "d": "Quebra do stent.", "e": "Uso de álcool."}, "answer": "b", "rationale": "Os stents farmacológicos reduziram drasticamente a reestenose, mas a doença arterial coronariana continua sendo sistêmica e progressiva.", "option_rationales": {"a": "Incorreta. Raro hoje em dia com DAPT.", "b": "Correta. Evolução natural da doença coronariana.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Stent", "SCA", "Seguimento"]}', 165, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o manejo da SCA em diabéticos, qual a preferência de estratégia de revascularização em multiarteriais (estudo FREEDOM)?", "options": {"a": "Intervenção Percutânea (ICP).", "b": "Cirurgia de Revascularização do Miocárdio (CRVM).", "c": "Apenas tratamento clínico.", "d": "Exercício físico.", "e": "Apenas aspirina."}, "answer": "b", "rationale": "Em diabéticos multiarteriais, a cirurgia mostrou menor mortalidade e menos reinfartos a longo prazo do que o stent.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Evidência clássica que guia as diretrizes.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Diabetes", "CRVM", "FREEDOM"]}', 166, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia mostra uma lesão em artéria marginal da circunflexa. O que significa o termo ''marginal''?", "options": {"a": "É uma artéria sem importância.", "b": "É um ramo da artéria coronária direita.", "c": "É o principal ramo da artéria circunflexa que irriga a parede lateral do ventrículo esquerdo.", "d": "É uma artéria do pulmão.", "e": "É a artéria da cabeça."}, "answer": "c", "rationale": "Anatomia coronariana: DA dá Diagonais e Septais; ACX dá Marginais.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Nomenclatura anatômica.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Anatomia", "SCA", "Vascular"]}', 167, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal causa de ''elevação espúria'' (falso-positiva) de troponina ultrassensível em atletas de elite após uma maratona?", "options": {"a": "Infarto agudo silencioso.", "b": "Extravasamento transitório de troponina do citosol dos miócitos devido ao estresse fisiológico extremo e sobrecarga mecânica supra-fisiológica, sem necrose irreversível.", "c": "Eles usam anabolizantes.", "d": "O laboratório erra.", "e": "Eles bebem muita água."}, "answer": "b", "rationale": "O exercício extremo pode causar micro-injúria miocárdica reversível.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fenômeno fisiológico conhecido em medicina do esporte.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Esporte", "Troponina", "Diagnóstico"]}', 168, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia mostra um vaso com aspecto de ''contas de rosário'' ou ''sacarrolhas''. Este achado é sugestivo de qual condição associada a espasmo coronariano severo ou displasia fibromuscular?", "options": {"a": "Dissecação espontânea da artéria coronária (SCAD).", "b": "Displasia fibromuscular ou vasoespasmo induzido por cocaína.", "c": "Normalidade.", "d": "Aterosclerose clássica.", "e": "Pneumonia."}, "answer": "b", "rationale": "O aspecto angiográfico sugere alternância de áreas de constrição e dilatação.", "option_rationales": {"a": "Incorreta. SCAD mostra dupla luz ou oclusão abrupta.", "b": "Correta. Diagnóstico diferencial importante.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Angiografia", "Diagnóstico", "SCA"]}', 169, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No manejo da SCA em idosos muito frágeis, qual o maior risco do uso de estatinas em altas doses (terapia intensiva)?", "options": {"a": "Nenhum.", "b": "Risco de mialgia, fraqueza muscular e rabdomiólise, podendo comprometer a mobilidade e o estado funcional.", "c": "Gosto ruim.", "d": "Cura a calvície.", "e": "Não funciona."}, "answer": "b", "rationale": "Idosos têm maior suscetibilidade a efeitos colaterais musculares e hepáticos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Segurança farmacológica na geriatria.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Estatinas", "Geriatria", "Segurança"]}', 170, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia mostra uma lesão ostial na artéria descendente anterior. Qual a dificuldade técnica deste tipo de lesão?", "options": {"a": "Dificuldade de posicionar o stent exatamente na origem, sem comprometer o tronco de esquerda ou deixar a lesão descoberta.", "b": "Nenhuma.", "c": "O paciente não pode respirar.", "d": "O stent não entra.", "e": "O contraste vaza."}, "answer": "a", "rationale": "Lesões ostiais exigem precisão milimétrica e frequentemente o uso de técnicas de visualização complementares (IVUS).", "option_rationales": {"a": "Correta. Desafio da anatomia coronariana.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Hemodinâmica", "Ostial", "SCA"]}', 171, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal indicação para o uso de nitratos sublinguais na estratégia de ''pill-in-the-pocket'' em pacientes estáveis?", "options": {"a": "Tomar todo dia.", "b": "Alívio imediato de episódios esporádicos de dor torácica anginosa desencadeada por esforço ou estresse emocional.", "c": "Curar a gripe.", "d": "Abaixar a pressão em casa rotineiramente.", "e": "Melhorar o sono."}, "answer": "b", "rationale": "Dão autonomia ao paciente para abortar crises anginosas.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Uso sob demanda.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Nitrato", "Angina"]}', 172, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal causa de insuficiência renal aguda após um cateterismo cardíaco em pacientes predispostos é:", "options": {"a": "Infecção.", "b": "Nefropatia induzida por contraste (NIC) e/ou microembolia de cristais de colesterol de placas da aorta manipulada (doença ateroembólica).", "c": "Falta de água.", "d": "Uso de aspirina.", "e": "Alimento estragado."}, "answer": "b", "rationale": "O contraste e a manipulação do cateter na aorta são os dois vilões renais.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação iatrogênica reconhecida.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Intervenção", "Rim", "Complicação"]}', 173, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual o achado ECG que sugere INFARTO DE VENTRÍCULO DIREITO quando se observa as derivações de rotina (padrão)?", "options": {"a": "Supra em V1 e infra em V2.", "b": "Supra de ST em parede inferior (DII, DIII, aVF) associado a supra em V1 (a derivação mais próxima do VD).", "c": "Onda T gigante em todas as derivações.", "d": "Inversão de onda P.", "e": "Intervalo PR curto."}, "answer": "b", "rationale": "O supra em V1 num contexto de infarto inferior deve acender o alerta para o comprometimento do VD.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Dica eletrocardiográfica valiosa.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "ECG", "Infarto de VD", "SCA"]}', 174, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia mostra uma lesão de 70% no tronco da coronária esquerda. O Heart Team opta pela cirurgia de revascularização. Qual o vaso escolhido como enxerto padrão-ouro para revascularizar a artéria descendente anterior (DA)?", "options": {"a": "Veia safena.", "b": "Artéria Torácica Interna Esquerda (Mamária).", "c": "Artéria Radial.", "d": "Artéria Femoral.", "e": "Prótese de plástico."}, "answer": "b", "rationale": "A mamária para a DA tem patência a longo prazo (10-15 anos) superior a qualquer outro conduto.", "option_rationales": {"a": "Incorreta. Patência menor que a mamária.", "b": "Correta. Padrão de excelência cirúrgica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Cirurgia", "Mamária", "CRVM"]}', 175, 'draft');
